mapper.select:
select action_name as actionName, system_type as SystemType, sum(cnt) as totalCount, ROUND(SUM(avg_duration*cnt)/SUM(cnt), 2) as avgDuration from ${routeInfo.dynamicTableName} where caller_service_name = #{param.serviceName} and caller_span_kind = 2 and span_kind = 3 and caller_target_name = #{param.targetNameHashKey}::uuid
and host_name = #{param.hostName}
AND (time >= #{dateParam.startUTC}::TIMESTAMPTZ AND time < #{dateParam.endUTC}::TIMESTAMPTZ)
group by system_type, action_name ORDER BY SUM(avg_duration * cnt) DESC LIMIT #{pageParam.pageSize} OFFSET #{pageParam.pageOffset}

SELECT target_name AS targetName, system_type AS SystemType, SUM(cnt) AS totalCount, SUM(avg_duration * cnt) / SUM(cnt) AS avgDuration FROM ${routeInfo.dynamicTableName} WHERE caller_service_name = #{param.serviceName} and caller_span_kind = 2 and span_kind = 3 and caller_target_name = #{param.targetNameHashKey}::uuid
and host_name = #{param.hostName}
AND (time >= #{dateParam.startUTC}::TIMESTAMPTZ AND time < #{dateParam.endUTC}::TIMESTAMPTZ)
GROUP BY system_type, target_name ORDER BY SUM(avg_duration * cnt) DESC LIMIT #{pageParam.pageSize} OFFSET #{pageParam.pageOffset}

SELECT caller_service_name as callerServiceName, caller_target_name as callerTargetName, SUM ( avg_duration * cnt ) AS totalTime, SUM ( cnt ) AS totalCount , ROUND( SUM ( avg_duration * cnt )/SUM ( cnt ), 2) as avgDuration FROM ${routeInfo.dynamicTableName} WHERE service_name = #{param.serviceName} and span_kind = 2 and target_name = #{param.targetNameHashKey}::uuid
and host_name = #{param.hostName}
AND (time >= #{dateParam.startUTC}::TIMESTAMPTZ AND time < #{dateParam.endUTC}::TIMESTAMPTZ)
GROUP BY caller_service_name, caller_target_name order by ${pageParam.sortBy} ${pageParam.sortOrder} LIMIT #{pageParam.pageSize} OFFSET #{pageParam.pageOffset};

select
   target_name                 as targetName,
   caller_target_name          as callerTargetName,
   ROUND(SUM(avg_duration*cnt)/SUM(cnt), 2) as avgDuration,
   sum(cnt)                    as totalCount,
   sum(error_num)              as totalError
from ${routeInfo.dynamicTableName}
where
  service_name = #{param.serviceName}
  and system_type = #{param.systemType}
  and span_kind = #{param.spanKind}

    and host_name = #{param.hostName}


    AND (time >= #{dateParam.startUTC}::TIMESTAMPTZ AND time < #{dateParam.endUTC}::TIMESTAMPTZ)

group by caller_target_name, target_name

select
    time_bucket('${param.strInterval}', time) AT TIME ZONE #{dateParam.timezone} as timeb,
    SUM(cnt) as totalCount,
    SUM(error_num) as totalError,
    ROUND(SUM(avg_duration*cnt)/SUM(cnt), 2) as avgDuration
from ${routeInfo.dynamicTableName}
where
    service_name = #{param.serviceName}
    and span_kind = #{param.spanKind}
    and target_name = #{param.targetNameHashKey}::uuid

        and system_type = #{param.systemType}


        and host_name = #{param.hostName}


    AND (time >= #{dateParam.startUTC}::TIMESTAMPTZ AND time < #{dateParam.endUTC}::TIMESTAMPTZ)

    and caller_target_name = #{param.callerTargetNameHashKey}::uuid
group by timeb
order by timeb
